function oppLev(o){return o.revMid/Math.max(o.maint,0.25);}
function fmtK(n){return n>=1000?"$"+(n%1000?(n/1000).toFixed(1):(n/1000))+"k":"$"+n;}
function mScatter(){
  const W=340,H=210,L=34,Rm=10,T=14,B=26,pw=W-L-Rm,ph=H-T-B,maxMaint=26,maxRev=8000;
  const aiColor={1:"#c0392b",2:"#e0a800",3:"#0099e5",4:"#1B2A4E",5:"#8BC34A"};
  let dots="";OPPS.forEach(o=>{const mx=Math.min(o.maint,maxMaint),rv=Math.min(o.revMid,maxRev);const x=L+(mx/maxMaint)*pw,y=T+ph-(rv/maxRev)*ph,r=2.5+o.ai;dots+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${aiColor[o.ai]}" fill-opacity="0.7"></circle>`;});
  let ax=`<line x1="${L}" y1="${T}" x2="${L}" y2="${T+ph}" stroke="var(--line)"></line><line x1="${L}" y1="${T+ph}" x2="${L+pw}" y2="${T+ph}" stroke="var(--line)"></line>`;
  ax+=`<text x="${L+pw/2}" y="${H-2}" font-size="8" text-anchor="middle" fill="var(--muted)">maintenance hrs/wk &#8594;</text>`;
  ax+=`<text x="9" y="${T+ph/2}" font-size="8" text-anchor="middle" fill="var(--muted)" transform="rotate(-90 9 ${T+ph/2})">monthly revenue &#8594;</text>`;
  ax+=`<text x="${L+3}" y="${T+7}" font-size="7.5" fill="var(--accent-ink)">best: low effort, high $</text>`;
  const legend=[5,4,3,2,1].map(a=>`<span class="lg"><span class="sw" style="background:${aiColor[a]}"></span>AI ${a}</span>`).join("");
  return `<div class="card"><strong>Revenue vs. maintenance</strong> <span class="sub">(dot size/color = AI-leverage)</span><svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" style="margin:6px 0">${ax}${dots}</svg><div class="mlg" style="display:flex;gap:12px;flex-wrap:wrap">${legend}</div><div class="sub">Each dot is one opportunity. Top-left is the passive sweet spot: high revenue, low upkeep. Bigger/greener dots are more AI-automatable.</div></div>`;
}
function oppPill(o){
  if(o.cat==="bigplay"||o.setupCost>=20000||(o.ai<=1&&o.maint>=15))return `<span class="pill risk">Long / heavy</span>`;
  if(o.ttrW<=6&&o.setupCost<2000)return `<span class="pill qw">Quick win</span>`;
  return `<span class="pill lp">Build-up</span>`;
}
function mCatBar(){const c={};OPPS.forEach(o=>c[o.cat]=(c[o.cat]||0)+1);const rows=Object.keys(OCAT).filter(k=>c[k]).map(k=>({l:OCAT[k],v:c[k],n:c[k]+""}));return mBars(rows);}
function oppTLDR(){
  const ai45=OPPS.filter(o=>o.ai>=4).length,quick=OPPS.filter(o=>o.ttrW<=4).length,passive=OPPS.filter(o=>o.maint<2&&o.setupCost<1000).length;
  const top=OPPS.slice().sort((a,b)=>oppLev(b)-oppLev(a))[0];
  let h=`<div class="tldr"><div class="t"><div class="v">${OPPS.length}</div><div class="k">ideas scanned</div></div><div class="t"><div class="v">${ai45}</div><div class="k">AI-leverage 4-5</div></div><div class="t"><div class="v">${passive}</div><div class="k">low-maint / low-cost</div></div></div>`;
  h+=mCallout("","Highest leverage right now",top.name+" — "+fmtK(top.revMid)+"/mo at ~"+top.maint+" hr/wk. Open the Passive shortlist for the top 10.");
  h+=`<div class="card"><strong>How the 80 break down by type</strong>`+mCatBar()+`</div>`;
  return h;
}
function oppCard(o,rank){
  const passive=(o.maint<2&&o.setupCost<1000);
  let h=`<div class="mcard">`;
  h+=`<div class="mt">${rank?`<span class="orank">${rank}</span>`:""}${esc(o.name)} <span class="mtag">${esc(OCAT[o.cat])}</span>${oppPill(o)}${passive?`<span class="mtag good">low-maintenance</span>`:""}</div>`;
  h+=`<div class="ochips"><span class="ochip ${o.maint<2?"good":""}">💤 ${o.maint} hr/wk</span><span class="ochip ${o.setupCost<1000?"good":""}">💵 ${fmtK(o.setupCost)} setup</span><span class="ochip">📈 ${fmtK(o.revLow)}-${fmtK(o.revUp)}/mo</span><span class="ochip ${o.ai>=4?"good":""}">🤖 AI ${o.ai}/5</span><span class="ochip">⏱ ${esc(o.ttr)}</span></div>`;
  h+=`<details><summary style="cursor:pointer;font-size:12.5px;color:var(--brand-text);font-weight:700">Details &amp; first 3 actions</summary><div style="font-size:12.5px;line-height:1.5;margin-top:6px">`;
  h+=`<div>${esc(o.what)}</div>`;
  h+=`<div style="margin-top:5px"><b>Why OBX:</b> ${esc(o.why)}</div>`;
  h+=`<div style="margin-top:5px"><b>Setup:</b> ${fmtK(o.setupCost)} + ~${o.setupHours} hrs · <b>First revenue:</b> ${esc(o.ttr)} · <b>Maint:</b> ${o.maint} hr/wk</div>`;
  h+=`<div style="margin-top:5px"><b>Revenue:</b> low ${fmtK(o.revLow)} · mid ${fmtK(o.revMid)} · upside ${fmtK(o.revUp)}/mo. ${esc(o.revWhy||"")}</div>`;
  h+=`<div style="margin-top:5px"><b>Risk:</b> ${esc(o.risk)}</div>`;
  h+=`<div style="margin-top:5px"><b>Monday morning:</b><ol style="margin:4px 0 0 18px;padding:0">${o.actions.map(a=>`<li>${esc(a)}</li>`).join("")}</ol></div>`;
  h+=`</div></details></div>`;
  return h;
}
