function mLaunch(){
  let h=`<div class="card" style="border-left:5px solid var(--accent)"><strong>First-30-days launch plans — top 5 passive picks</strong><div class="sub">The highest income-per-hour plays, each broken into a week-by-week start.</div></div>`;
  h+=OLAUNCH.map(p=>mAcc(p.name,`<div class="sub" style="margin-bottom:6px">${esc(p.summary)}</div>`+p.weeks.map(w=>`<div class="mcard"><div class="mt" style="font-size:13px">${esc(w.w)}</div><ol style="margin:5px 0 0 18px;padding:0;font-size:12.5px;line-height:1.5">${w.items.map(i=>`<li>${esc(i)}</li>`).join("")}</ol></div>`).join("")+`<div style="font-size:12.5px;margin-top:4px"><b>Success marker:</b> ${esc(p.success)}</div>`,false)).join("");
  return h;
}
function oppHandoff(o){return (o.cat==="service"||o.cat==="tourist")&&o.ai<=2;}
function mTable(){
  let list=OPPS.slice();
  const sorters={lev:(a,b)=>oppLev(b)-oppLev(a),rev:(a,b)=>b.revMid-a.revMid,setup:(a,b)=>a.setupCost-b.setupCost,maint:(a,b)=>a.maint-b.maint,ai:(a,b)=>b.ai-a.ai,speed:(a,b)=>a.ttrW-b.ttrW};
  list.sort(sorters[OPPSORT]||sorters.lev);
  if(OPPCAT!=="all")list=list.filter(o=>o.cat===OPPCAT);
  let h=`<div class="osort">`+[["lev","Leverage"],["rev","Revenue"],["setup","Setup"],["maint","Maint"],["ai","AI"],["speed","Speed"]].map(s=>`<button class="subbtn ${OPPSORT===s[0]?"on":""}" onclick="oppSort('${s[0]}')">${s[1]}</button>`).join("")+`</div>`;
  const cats=[["all","All"]].concat(Object.keys(OCAT).map(k=>[k,OCAT[k]]));
  h+=`<div class="osort">`+cats.map(c=>`<button class="subbtn ${OPPCAT===c[0]?"on":""}" onclick="oppCat('${c[0]}')">${esc(c[1])}</button>`).join("")+`</div>`;
  h+=`<p class="muted" style="margin:4px">${list.length} shown · scroll sideways for all columns.</p>`;
  h+=`<div style="overflow-x:auto"><table class="otable"><thead><tr><th>Opportunity</th><th>Category</th><th>Maint/wk</th><th>Setup</th><th>Rev/mo (mid)</th><th>AI</th><th>1st rev</th><th>Team</th></tr></thead><tbody>`;
  h+=list.map(o=>`<tr><td>${esc(o.name)}</td><td>${esc(OCAT[o.cat])}</td><td>${o.maint}h</td><td>${fmtK(o.setupCost)}</td><td>${fmtK(o.revMid)}</td><td>${o.ai}/5</td><td>${esc(o.ttr)}</td><td>${oppHandoff(o)?"Brothers":"Ray"}</td></tr>`).join("");
  h+=`</tbody></table></div>`;
  return h;
}
let OPPVIEW="shortlist",OPPSORT="lev",OPPCAT="all",OPPTEAM="all";
function rOpps(){
  let h=`<div class="secthd"><h2>OBX opportunity scan</h2></div>`;
  h+=`<p class="muted" style="margin:0 4px 6px">${OPPS.length} income ideas for the Outer Banks, weighted toward low-maintenance and AI-automatable plays. Tap any card for details + the first 3 moves.</p>`;
  h+=oppTLDR();
  h+=`<div class="subnav" style="flex-wrap:wrap"><button class="subbtn ${OPPVIEW==="shortlist"?"on":""}" onclick="oppView('shortlist')">⚡ Passive shortlist</button><button class="subbtn ${OPPVIEW==="quick"?"on":""}" onclick="oppView('quick')">🚀 Quick wins</button><button class="subbtn ${OPPVIEW==="launch"?"on":""}" onclick="oppView('launch')">🗓 Launch plans</button><button class="subbtn ${OPPVIEW==="cases"?"on":""}" onclick="oppView('cases')">✅ Proof</button><button class="subbtn ${OPPVIEW==="table"?"on":""}" onclick="oppView('table')">▦ Table</button><button class="subbtn ${OPPVIEW==="all"?"on":""}" onclick="oppView('all')">📂 All ${OPPS.length}</button></div>`;
  let list=OPPS.slice();
  if(OPPVIEW==="launch"){h+=mLaunch();view.innerHTML=h;view.scrollTop=0;return;}
  if(OPPVIEW==="cases"){h+=mCases();view.innerHTML=h;view.scrollTop=0;return;}
  if(OPPVIEW==="table"){h+=mTable();view.innerHTML=h;view.scrollTop=0;return;}
  if(OPPVIEW==="shortlist"){
    list.sort((a,b)=>oppLev(b)-oppLev(a));list=list.slice(0,10);
    h+=mScatter();
    h+=`<p class="muted" style="margin:0 4px 8px">Top 10 by leverage = monthly revenue ÷ maintenance hours. Highest passive-income-per-hour first.</p>`;
    h+=list.map((o,i)=>oppCard(o,i+1)).join("");
  } else if(OPPVIEW==="quick"){
    list=list.filter(o=>o.ttrW<=4).sort((a,b)=>oppLev(b)-oppLev(a));
    h+=`<p class="muted" style="margin:0 4px 8px">${list.length} ideas you could launch within ~30 days, best leverage first.</p>`;
    h+=list.map(o=>oppCard(o)).join("");
  } else {
    h+=`<div class="osort">`+[["lev","Leverage"],["rev","Revenue"],["setup","Setup $"],["maint","Maint hrs"],["ai","AI"],["speed","Speed"]].map(s=>`<button class="subbtn ${OPPSORT===s[0]?"on":""}" onclick="oppSort('${s[0]}')">${s[1]}</button>`).join("")+`</div>`;
    const cats=[["all","All"]].concat(Object.keys(OCAT).map(k=>[k,OCAT[k]]));
    h+=`<div class="osort">`+cats.map(c=>`<button class="subbtn ${OPPCAT===c[0]?"on":""}" onclick="oppCat('${c[0]}')">${esc(c[1])}</button>`).join("")+`</div>`;
    if(OPPCAT!=="all")list=list.filter(o=>o.cat===OPPCAT);
    h+=`<div class="osort"><button class="subbtn ${OPPTEAM==="all"?"on":""}" onclick="oppTeam('all')">Anyone</button><button class="subbtn ${OPPTEAM==="ray"?"on":""}" onclick="oppTeam('ray')">Owner-only (Ray)</button><button class="subbtn ${OPPTEAM==="bros"?"on":""}" onclick="oppTeam('bros')">Hand-off (Pierce/Chase)</button></div>`;
    if(OPPTEAM==="bros")list=list.filter(oppHandoff);else if(OPPTEAM==="ray")list=list.filter(o=>!oppHandoff(o));
    const sorters={lev:(a,b)=>oppLev(b)-oppLev(a),rev:(a,b)=>b.revMid-a.revMid,setup:(a,b)=>a.setupCost-b.setupCost,maint:(a,b)=>a.maint-b.maint,ai:(a,b)=>b.ai-a.ai,speed:(a,b)=>a.ttrW-b.ttrW};
    list.sort(sorters[OPPSORT]||sorters.lev);
    h+=`<p class="muted" style="margin:4px">${list.length} shown.</p>`;
    h+=list.map(o=>oppCard(o)).join("");
  }
  view.innerHTML=h;view.scrollTop=0;
}
window.oppView=function(v){OPPVIEW=v;render();};
window.oppSort=function(s){OPPSORT=s;render();};
window.oppCat=function(c){OPPCAT=c;render();};
window.oppTeam=function(t){OPPTEAM=t;render();};

